# ── 8. field_value_matches_tooltip via scene structure ───────────────────


def test_numeric_field_values_in_tooltips():
    """Selection fields with numeric values must be serialized correctly
    in tooltips (as strings that can round-trip through the field_value_matches_tooltip
    comparison on the Rust side)."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0], "score": [99.5, 100.5]})
    sel = selection_point(fields=["score"], name="num_sel")
    chart = (
        fm.Chart(df)
        .mark_point()
        .encode(x="x:Q", y="y:Q")
        .add_selection(sel)
        .properties(width=200, height=200)
    )
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    panel = scene["panels"][0]
    found_score = False
    for batch in panel["marks"]:
        tooltips = batch.get("tooltips")
        if tooltips is not None:
            for tip in tooltips:
                for f in tip.get("fields", []):
                    if f["name"] == "score":
                        found_score = True
                        # Value must be parseable as float
                        float(f["value"])
    assert found_score, "numeric selection field 'score' must appear in tooltips"


# ── 9. SelectionMark edge cases ─────────────────────────────────────────


def test_selection_mark_default_values():
    """SelectionMark with no arguments must have sensible defaults."""
    m = SelectionMark()
    d = m.to_spec_dict()
    assert d["fill_opacity"] == 0.3
    assert d["stroke_opacity"] == 1.0
    assert d["stroke_width"] == 1.0
    assert "fill" not in d  # None fill not serialized
    assert "stroke" not in d
    assert "stroke_dash" not in d


def test_selection_mark_hex_parsing():
    """SelectionMark hex colours must parse correctly into r/g/b/a dicts."""
    m = SelectionMark(fill="#ff8800", stroke="#00ff0080")
    d = m.to_spec_dict()
    assert d["fill"]["r"] == 255
    assert d["fill"]["g"] == 136
    assert d["fill"]["b"] == 0
    assert d["fill"]["a"] == 255
    assert d["stroke"]["a"] == 128  # 8-char hex includes alpha


# ── 10. Selection with bar marks ────────────────────────────────────────


def test_bar_chart_with_selection_produces_valid_scene():
    """A bar chart with selection and conditional must produce valid scene JSON
    with rect marks that can have conditionals applied."""
    df = pl.DataFrame({"x": ["a", "b", "c"], "y": [10.0, 20.0, 30.0]})
    sel = selection_point(fields=["x"], name="bar_sel")
    cond = sel.when(fm.Color("x")).otherwise(value("#cccccc"))
    chart = (
        fm.Chart(df)
        .mark_bar()
        .encode(x="x:N", y="y:Q")
        .add_selection(sel)
        .conditional(cond)
        .properties(width=200, height=200)
    )
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    assert "panels" in scene
    # Must have mark batches
    marks = scene["panels"][0]["marks"]
    assert len(marks) >= 1


# ── 11. value() edge cases ──────────────────────────────────────────────


def test_value_with_integer_opacity():
    """value(1) must produce an opacity encoding with value 1.0."""
    v = value(1)
    d = _resolve_encoding_value(v)
    assert d["kind"] == "opacity"
    assert d["value"] == 1.0


def test_value_with_hex_color():
    """value('#ff0000') must produce a color encoding."""
    v = value("#ff0000")
    d = _resolve_encoding_value(v)
    assert d["kind"] == "color"
    assert d["value"]["r"] == 255
    assert d["value"]["g"] == 0


# ── 12. add_selection with no arguments ──────────────────────────────────


def test_add_selection_no_args():
    """add_selection() with no arguments must not crash and produce a chart
    with no selections."""
    df = _small_df()
    chart = (
        fm.Chart(df)
        .mark_point()
        .encode(x="x:Q", y="y:Q")
        .add_selection()
        .properties(width=200, height=200)
    )
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    selections = scene.get("selections", [])
    assert len(selections) == 0


def test_add_selection_multiple_at_once():
    """add_selection(sel1, sel2, sel3) must register all three selections."""
    df = _small_df()
    s1 = selection_point(name="s1")
    s2 = selection_interval(name="s2")
    s3 = selection_point(name="s3")
    chart = (
        fm.Chart(df)
        .mark_point()
        .encode(x="x:Q", y="y:Q")
        .add_selection(s1, s2, s3)
        .properties(width=200, height=200)
    )
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    sel_names = {s["name"] for s in scene.get("selections", [])}
    assert sel_names == {"s1", "s2", "s3"}


# ── 13. Selection immutability ──────────────────────────────────────────


def test_selection_is_frozen():
    """Selection dataclass is frozen -- attributes cannot be mutated."""
    sel = selection_point(name="frozen_sel")
    with pytest.raises(AttributeError):
        sel.name = "modified"


def test_conditional_spec_is_frozen():
    """ConditionalSpec dataclass is frozen."""
    sel = selection_point(name="f_sel")
    cond = sel.when(fm.Color("g")).otherwise(value("#ccc"))
    with pytest.raises(AttributeError):
        cond.selection_name = "modified"
